template <class T1, class T2> const auto min(const T1 &x, const T2 &y) {
  return x > y ? y : x;
}

template <class T1, class T2> const auto max(const T1 &x, const T2 &y) {
  return x > y ? x : y;
}

template <class T> void swap(T &a, T &b) {
  T __t = a;
  a = b;
  b = __t;
}

